/**
 * External function: submit_check_in (DEC-031 v1.1 inline check-ins).
 *
 * AMD module calls this on panel submit. Forwards the choice (strategy_id
 * or no_strategy=true) plus the client-generated Idempotency-Key to
 * POST /api/v1/check-in. Returns {ok, error?, response_id?}.
 *
 * Capability: enrolment in $courseid (BLOCKER #2).
 *
 * @package    local_srl_advisor
 * @copyright  2026 Andrew Schwabe
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

namespace local_srl_advisor\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use context_course;

/**
 * External function to submit an inline check-in response.
 *
 * @package    local_srl_advisor
 * @copyright  2026 Andrew Schwabe
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class submit_check_in extends external_api {
    /**
     * Declare parameters for the submit_check_in external function.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'courseid'       => new external_value(PARAM_INT, 'Moodle course id', VALUE_REQUIRED),
            'taskid'         => new external_value(PARAM_INT, 'Backend StudentTask.id', VALUE_REQUIRED),
            'strategyid'     => new external_value(
                PARAM_INT,
                'Selected strategy id; 0 when no_strategy=true or other_text used',
                VALUE_DEFAULT,
                0
            ),
            'nostrategy'     => new external_value(
                PARAM_BOOL,
                'True when the student explicitly picked "no strategy"',
                VALUE_DEFAULT,
                false
            ),
            'othertext'      => new external_value(
                PARAM_TEXT,
                'Free-text strategy (1-200 chars) when student picked "Other"; empty otherwise',
                VALUE_DEFAULT,
                ''
            ),
            'responsetimems' => new external_value(
                PARAM_INT,
                'Milliseconds between render and submit (0 if unknown)',
                VALUE_DEFAULT,
                0
            ),
            'idempotencykey' => new external_value(
                PARAM_ALPHANUMEXT,
                'UUID v4 generated by AMD; replays return cached response',
                VALUE_REQUIRED
            ),
        ]);
    }

    /**
     * Submit an inline check-in choice to the SRL Advisor backend.
     *
     * @param int    $courseid       Moodle course id.
     * @param int    $taskid         Backend StudentTask id.
     * @param int    $strategyid     Selected strategy id; 0 when no strategy or other.
     * @param bool   $nostrategy     True when student picked no strategy.
     * @param string $othertext      Free-text strategy when student picked Other.
     * @param int    $responsetimems Milliseconds between render and submit.
     * @param string $idempotencykey UUID v4 generated by AMD.
     * @return array {ok, error, response_id}
     */
    public static function execute(
        int $courseid,
        int $taskid,
        int $strategyid = 0,
        bool $nostrategy = false,
        string $othertext = '',
        int $responsetimems = 0,
        string $idempotencykey = ''
    ): array {
        global $CFG, $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'courseid'        => $courseid,
            'taskid'          => $taskid,
            'strategyid'      => $strategyid,
            'nostrategy'      => $nostrategy,
            'othertext'       => $othertext,
            'responsetimems'  => $responsetimems,
            'idempotencykey'  => $idempotencykey,
        ]);

        $context = context_course::instance($params['courseid']);
        self::validate_context($context);

        if (!has_capability('local/srl_advisor:participate', $context, $USER)) {
            return ['ok' => false, 'error' => 'not_enrolled', 'response_id' => 0];
        }

        $backendurl = trim((string)get_config('local_srl_advisor', 'backend_url'));
        $apitoken   = trim((string)get_config('local_srl_advisor', 'api_token'));
        if (empty($backendurl) || empty($apitoken)) {
            return ['ok' => false, 'error' => 'plugin_not_configured', 'response_id' => 0];
        }

        require_once($CFG->dirroot . '/local/srl_advisor/lib.php');

        $pseudo = hash('sha256', $USER->id . $CFG->siteidentifier);
        $jwt = local_srl_advisor_build_jwt($params['courseid'], $pseudo, $apitoken);

        $othertrimmed = trim((string)($params['othertext'] ?? ''));
        $body = [
            'task_id'           => $params['taskid'],
            'strategy_id'       => $params['strategyid'] > 0 ? $params['strategyid'] : null,
            'no_strategy'       => $params['nostrategy'],
            'other_text'        => $othertrimmed !== '' ? $othertrimmed : null,
            'response_time_ms'  => $params['responsetimems'] > 0 ? $params['responsetimems'] : null,
        ];
        $headers = ['Idempotency-Key: ' . $params['idempotencykey']];

        $result = local_srl_advisor_relay_backend_call(
            'inline_post',
            '/api/v1/check-in',
            'POST',
            $body,
            $jwt,
            5,
            $headers
        );

        if (!$result['ok']) {
            return [
                'ok'           => false,
                'error'        => self::map_error($result),
                'response_id'  => 0,
            ];
        }

        $data = $result['data'];
        return [
            'ok'           => true,
            'error'        => '',
            'response_id'  => isset($data['response_id']) ? (int)$data['response_id'] : 0,
        ];
    }

    /**
     * Map relay-helper error_kind + http_code to a stable short string the AMD
     * module can branch on without parsing free-form server detail text.
     *
     * @param array $result Relay-helper result array (error_kind, http_code, ...).
     * @return string Stable short error code for the AMD module.
     */
    private static function map_error(array $result): string {
        $kind = $result['error_kind'] ?? 'unknown';
        $code = (int)($result['http_code'] ?? 0);
        if ($kind === 'transport') {
            return 'backend_unreachable';
        }
        if ($kind === 'parse') {
            return 'bad_response';
        }
        if ($kind === 'backend') {
            if ($code === 400) {
                return 'invalid_payload';
            }
            if ($code === 401) {
                return 'auth_expired';
            }
            if ($code === 404) {
                return 'task_not_found';
            }
            if ($code === 409) {
                return 'already_completed';
            }
            if ($code === 410) {
                return 'task_expired';
            }
            if ($code === 429) {
                return 'rate_limited';
            }
            return 'backend_error';
        }
        return 'unknown';
    }

    /**
     * Describe the return value of submit_check_in.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'ok'           => new external_value(PARAM_BOOL, 'True on success'),
            'error'        => new external_value(PARAM_TEXT, 'Short error tag; empty on success'),
            'response_id'  => new external_value(PARAM_INT, 'Backend SurveyResponse.id on success, 0 otherwise'),
        ]);
    }
}
